mapper.select:
SELECT ID, EXTENSION, TYPE, IS_BLOCKED
  FROM FILE_EXTENSION_POLICY
 WHERE EXTENSION = #{extension}

mapper.update:
UPDATE FILE_EXTENSION_POLICY
   SET IS_BLOCKED = #{blocked}
 WHERE EXTENSION = #{extension}
   AND TYPE = 'FIXED'

mapper.delete:
DELETE FROM FILE_EXTENSION_POLICY
 WHERE ID = #{id}
   AND TYPE = 'CUSTOM'
